"use client";
import {
  Children,
  cloneElement,
  isValidElement,
  useId,
  type ReactNode,
  type ReactElement,
} from "react";
import { Layers3, Box } from "lucide-react";
import { money } from "../lib/api";
export function Brand() {
  return (
    <div className="brand">
      <span className="brand-icon">
        <Layers3 size={22} />
      </span>
      <span>
        OrderMesh<span className="brand-sub">AI LITE</span>
      </span>
    </div>
  );
}
export function Badge({
  children,
  kind = "neutral",
}: {
  children: ReactNode;
  kind?: string;
}) {
  return <span className={`badge ${kind}`}>{children}</span>;
}
export function Empty({ title, detail }: { title: string; detail: string }) {
  return (
    <div className="empty">
      <Box size={30} />
      <h3>{title}</h3>
      <p>{detail}</p>
    </div>
  );
}
export function Field({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  const id = useId();
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      {Children.map(children, (child) =>
        isValidElement(child) &&
        ["input", "select", "textarea"].includes(child.type as string)
          ? cloneElement(child as ReactElement<{ id: string }>, { id })
          : child,
      )}
    </div>
  );
}

export function Metric({
  label,
  value,
  note,
  icon,
  color,
}: {
  label: string;
  value: string;
  note: string;
  icon: ReactNode;
  color: string;
}) {
  return (
    <section className="metric">
      <div>
        <span>{label}</span>
        <span className={`metric-icon ${color}`}>{icon}</span>
      </div>
      <strong>{value}</strong>
      <p>{note}</p>
    </section>
  );
}
export function SalesChart({
  data,
}: {
  data: { date: string; total_minor: number }[];
}) {
  const max = Math.max(...data.map((d) => d.total_minor), 10000);
  return (
    <div
      className="sales-chart"
      role="img"
      aria-label={`Order value over the last seven days. ${data.map((d) => `${d.date}: ${money(d.total_minor)}`).join(", ")}`}
    >
      <div className="chart-y">
        <span>{money(max)}</span>
        <span>{money(max / 2)}</span>
        <span>0</span>
      </div>
      <div className="chart-bars">
        <div className="chart-grid" />
        {data.map((d) => (
          <div className="chart-column" key={d.date}>
            <div className="bar-slot">
              <div
                className={`chart-bar ${d.total_minor ? "" : "zero"}`}
                style={{
                  height: `${Math.max((d.total_minor / max) * 100, 1)}%`,
                }}
                title={`${d.date}: ${money(d.total_minor)}`}
              />
            </div>
            <span>
              {new Date(`${d.date}T12:00:00`).toLocaleDateString("en-GB", {
                weekday: "short",
              })}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
